#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVaultSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = VaultSession

    public static func lift(_ handle: UInt64) throws -> VaultSession {
        return VaultSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: VaultSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VaultSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: VaultSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeVaultSession_lift(_ handle: UInt64) throws -> VaultSession {
    return try FfiConverterTypeVaultSession.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeVaultSession_lower(_ value: VaultSession) -> UInt64 {
    return FfiConverterTypeVaultSession.lower(value)
}




