        /**
         * Words mode: how many words (3–10, clamped).
         */words: UInt32, 
        /**
         * Words mode: what separates them.
         */separator: WordSeparator, 
        /**
         * Words mode: capitalize each word.
         */capitalize: Bool, 
        /**
         * Words mode: append one random digit.
